• Support claims with textual evidence and warrants.
• Revise summary into analysis.',1,45,'unit-1',NULL) ON CONFLICT("id") DO UPDATE SET "title"=excluded."title","description"=excluded."description","content"=excluded."content","objectives"=excluded."objectives","order"=excluded."order","durationMin"=excluded."durationMin","sectionKey"=excluded."sectionKey","courseId"=excluded."courseId","videoUrl"=excluded."videoUrl";
